import yfinance as yf; T=[x.strip() for x in open("stocks.txt",encoding="utf-8") if x.strip()]; D=yf.download(T,period="3mo",progress=False,auto_adjust=True); C=D["Close"]; V=D["Volume"]; F=lambda t:(lambda c,v:(lambda p,var,mm,rvol,rsi:(t,max(0,min(100,(35 if p>mm else -20)+(25 if 3<var<8 else 10 if 0<=var<=3 else -25 if var<=-3 else 0)+(20 if rvol>=1.5 else 10 if rvol>=1 else 0)+(20 if 50<=rsi<=65 else 10 if 45<=rsi<75 else -30))),"SURCHAUFFE" if var>=8 or rsi>=75 else "ACHAT" if (p>mm and 3<var<8 and 50<=rsi<70) else "SURVEILLANCE" if p>mm and rsi>=40 else "AUCUN SIGNAL",var,rsi,rvol))(float(c.iloc[-2]),(float(c.iloc[-2])/float(c.iloc[-7])-1)*100,float(c.iloc[-21:-1].mean()),float(v.iloc[-2])/float(v.iloc[-22:-2].mean()),100-(100/(1+(c.diff().iloc[-15:-1].clip(lower=0).mean()/(-c.diff().iloc[-15:-1].clip(upper=0).mean()))))))(C[t].dropna(),V[t].reindex(C[t].dropna().index).dropna()); R=sorted([F(t) for t in T if t in C.columns and C[t].dropna().shape[0]>=22],key=lambda x:x[1],reverse=True); print("CLASSEMENT AJUSTE AU RISQUE\n"+"\n".join(f"{i+1}. {x[0]} | Score {x[1]}/100 | {x[2]} | Var5j {x[3]:+.2f}% | RSI {x[4]:.1f} | RVOL {x[5]:.2f}" for i,xi,x in enumerate(R)))
